CREATE TABLE tenant(id uuid PRIMARY KEY, code varchar(80) UNIQUE NOT NULL, name text NOT NULL, status text NOT NULL CHECK(status IN ('DRAFT','ACTIVE','SUSPENDED','ARCHIVED')), settings jsonb NOT NULL DEFAULT '{}', row_version bigint NOT NULL DEFAULT 1, created_at timestamptz DEFAULT now(), updated_at timestamptz DEFAULT now());
CREATE TABLE business_user(id uuid PRIMARY KEY, code text UNIQUE NOT NULL, name text NOT NULL, platform_admin boolean NOT NULL DEFAULT false);
CREATE TABLE role(tenant_id uuid REFERENCES tenant, code text, name text NOT NULL, actions jsonb NOT NULL, row_version bigint NOT NULL DEFAULT 1, PRIMARY KEY(tenant_id,code));
CREATE TABLE tenant_member(id uuid PRIMARY KEY,tenant_id uuid REFERENCES tenant,user_id uuid REFERENCES business_user,active boolean NOT NULL DEFAULT true,roles jsonb NOT NULL DEFAULT '[]',category_scope jsonb NOT NULL DEFAULT '["*"]',row_version bigint NOT NULL DEFAULT 1,UNIQUE(tenant_id,user_id));
CREATE TABLE category(id uuid PRIMARY KEY, tenant_id uuid REFERENCES tenant,code text NOT NULL,name text NOT NULL,parent_id uuid,active boolean NOT NULL DEFAULT true,approval_role text NOT NULL DEFAULT 'APPROVER',publish_role text NOT NULL DEFAULT 'PUBLISHER',default_schema_id uuid,row_version bigint NOT NULL DEFAULT 1,UNIQUE(tenant_id,code),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,parent_id) REFERENCES category(tenant_id,id));
CREATE TABLE metadata(id uuid PRIMARY KEY,tenant_id uuid REFERENCES tenant,kind text NOT NULL,code text NOT NULL,version int NOT NULL,active boolean NOT NULL DEFAULT true,data jsonb NOT NULL,row_version bigint NOT NULL DEFAULT 1,UNIQUE(tenant_id,kind,code,version),UNIQUE(tenant_id,id));
CREATE TABLE reference_entity(id text,tenant_id uuid REFERENCES tenant,type text NOT NULL,name text NOT NULL,active boolean DEFAULT true,data jsonb NOT NULL DEFAULT '{}',row_version bigint NOT NULL DEFAULT 1,PRIMARY KEY(tenant_id,type,id));
CREATE TABLE schema_version(id uuid PRIMARY KEY,tenant_id uuid REFERENCES tenant,category_id uuid NOT NULL,version int NOT NULL,status text NOT NULL DEFAULT 'DRAFT' CHECK(status IN ('DRAFT','REVIEW','PUBLISHED','RETIRED')),bundle jsonb NOT NULL,created_by uuid REFERENCES business_user,submitted_by uuid REFERENCES business_user,row_version bigint NOT NULL DEFAULT 1,created_at timestamptz DEFAULT now(),UNIQUE(tenant_id,category_id,version),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,category_id) REFERENCES category(tenant_id,id));
ALTER TABLE category ADD CONSTRAINT category_schema_tenant FOREIGN KEY(tenant_id,default_schema_id) REFERENCES schema_version(tenant_id,id);
CREATE TABLE material(id uuid PRIMARY KEY,tenant_id uuid REFERENCES tenant,category_id uuid NOT NULL,schema_version_id uuid NOT NULL,material_no varchar(128),number_source text NOT NULL DEFAULT 'GENERATED',parse_rule_version_id uuid,material_name text NOT NULL,base_unit_code text NOT NULL DEFAULT 'pcs',status text NOT NULL DEFAULT 'DRAFT' CHECK(status IN ('DRAFT','IN_REVIEW','ACTIVE','INACTIVE')),attributes jsonb NOT NULL,original_input jsonb NOT NULL,reference_snapshot jsonb NOT NULL DEFAULT '{}',row_version bigint NOT NULL DEFAULT 1,published_version bigint,created_by uuid REFERENCES business_user,updated_by uuid REFERENCES business_user,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now(),UNIQUE(tenant_id,material_no),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,category_id) REFERENCES category(tenant_id,id),FOREIGN KEY(tenant_id,schema_version_id) REFERENCES schema_version(tenant_id,id),CHECK(status NOT IN ('ACTIVE','INACTIVE') OR material_no IS NOT NULL));
CREATE TABLE material_revision(tenant_id uuid,material_id uuid,row_version bigint,snapshot jsonb NOT NULL,actor uuid,reason text,request_id uuid,created_at timestamptz DEFAULT now(),PRIMARY KEY(tenant_id,material_id,row_version),FOREIGN KEY(tenant_id,material_id) REFERENCES material(tenant_id,id));
CREATE TABLE material_projection(tenant_id uuid,material_id uuid,attribute_code text,kind text,num_value numeric,text_value text,bool_value boolean,date_value date,PRIMARY KEY(tenant_id,material_id,attribute_code),FOREIGN KEY(tenant_id,material_id) REFERENCES material(tenant_id,id));
CREATE INDEX projection_number ON material_projection(tenant_id,attribute_code,num_value);
CREATE INDEX projection_text ON material_projection(tenant_id,attribute_code,text_value);
CREATE INDEX material_search ON material(tenant_id,category_id,updated_at,id);
CREATE INDEX material_attributes ON material USING gin(attributes);
CREATE TABLE material_unique_key(tenant_id uuid,category_id uuid,key_hash text,material_id uuid,PRIMARY KEY(tenant_id,category_id,key_hash),FOREIGN KEY(tenant_id,material_id) REFERENCES material(tenant_id,id));
CREATE TABLE material_relation(tenant_id uuid,material_id uuid,replacement_id uuid,reason text,PRIMARY KEY(tenant_id,material_id,replacement_id),FOREIGN KEY(tenant_id,material_id) REFERENCES material(tenant_id,id),FOREIGN KEY(tenant_id,replacement_id) REFERENCES material(tenant_id,id));
CREATE TABLE material_request(id uuid PRIMARY KEY,tenant_id uuid,material_id uuid,kind text NOT NULL,state text NOT NULL DEFAULT 'DRAFT',base_version bigint NOT NULL,candidate jsonb NOT NULL,submitted_by uuid,reason text NOT NULL DEFAULT '',row_version bigint NOT NULL DEFAULT 1,source_system_id uuid,source_message_id text,created_at timestamptz DEFAULT now(),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,material_id) REFERENCES material(tenant_id,id));
CREATE TABLE approval_action(id uuid PRIMARY KEY,tenant_id uuid,object_id uuid,object_type text,actor uuid,action text,comment text,created_at timestamptz DEFAULT now());
CREATE TABLE idempotency_record(tenant_id uuid,client text,operation text,key text,body_hash text NOT NULL,result jsonb NOT NULL,created_at timestamptz DEFAULT now(),PRIMARY KEY(tenant_id,client,operation,key));
CREATE TABLE number_sequence(tenant_id uuid,rule_id uuid,name text,period text,next_value bigint NOT NULL,PRIMARY KEY(tenant_id,rule_id,name,period));
CREATE TABLE operation_log(id uuid PRIMARY KEY,tenant_id uuid REFERENCES tenant,object_id text,object_type text,category_id uuid,version bigint,action text,actor text,reason text,diff jsonb NOT NULL,trace_id text,created_at timestamptz DEFAULT now());
CREATE TABLE file_record(id uuid PRIMARY KEY,tenant_id uuid REFERENCES tenant,category_id uuid,name text,kind text,content bytea,checksum text,row_count bigint,query jsonb,created_at timestamptz DEFAULT now(),cleaned_at timestamptz);
CREATE TABLE import_job(id uuid PRIMARY KEY,tenant_id uuid REFERENCES tenant,category_id uuid,file_id uuid REFERENCES file_record,schema_id uuid,status text NOT NULL,previous_stage text,config jsonb NOT NULL,actor uuid,reason text,row_version bigint DEFAULT 1,created_at timestamptz DEFAULT now(),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,category_id) REFERENCES category(tenant_id,id),FOREIGN KEY(tenant_id,schema_id) REFERENCES schema_version(tenant_id,id));
CREATE TABLE staging_row(tenant_id uuid,job_id uuid,row_no int,source jsonb NOT NULL,candidate jsonb,state text NOT NULL DEFAULT 'PENDING',errors jsonb NOT NULL DEFAULT '[]',material_id uuid,request_id uuid,row_version bigint DEFAULT 1,PRIMARY KEY(tenant_id,job_id,row_no),FOREIGN KEY(tenant_id,job_id) REFERENCES import_job(tenant_id,id));
CREATE TABLE integration_system(id uuid PRIMARY KEY,tenant_id uuid REFERENCES tenant,code text NOT NULL,name text NOT NULL,direction text NOT NULL DEFAULT 'BOTH',config jsonb NOT NULL,active boolean NOT NULL DEFAULT false,paused boolean NOT NULL DEFAULT false,default_mapping_id uuid,credential_hash text,row_version bigint DEFAULT 1,UNIQUE(tenant_id,code),UNIQUE(tenant_id,id));
CREATE TABLE mapping_version(id uuid PRIMARY KEY,tenant_id uuid,system_id uuid,version int NOT NULL,state text NOT NULL DEFAULT 'DRAFT',config jsonb NOT NULL,row_version bigint DEFAULT 1,UNIQUE(tenant_id,system_id,version),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,system_id) REFERENCES integration_system(tenant_id,id));
ALTER TABLE integration_system ADD CONSTRAINT system_mapping_tenant FOREIGN KEY(tenant_id,default_mapping_id) REFERENCES mapping_version(tenant_id,id);
CREATE TABLE external_identity(tenant_id uuid,system_id uuid,external_id text,material_id uuid,confirmed_version bigint,digest text,PRIMARY KEY(tenant_id,system_id,external_id),UNIQUE(tenant_id,system_id,material_id),FOREIGN KEY(tenant_id,system_id) REFERENCES integration_system(tenant_id,id),FOREIGN KEY(tenant_id,material_id) REFERENCES material(tenant_id,id));
CREATE TABLE outbox_event(id uuid PRIMARY KEY,tenant_id uuid,material_id uuid,row_version bigint,previous_published_version bigint,event_type text,snapshot jsonb NOT NULL,source_system_id uuid,trace_id text,created_at timestamptz DEFAULT now(),UNIQUE(tenant_id,material_id,row_version),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,material_id) REFERENCES material(tenant_id,id));
CREATE TABLE delivery(id uuid PRIMARY KEY,tenant_id uuid,event_id uuid,system_id uuid,mapping_id uuid,state text NOT NULL DEFAULT 'PENDING',attempts int NOT NULL DEFAULT 0,next_attempt_at timestamptz NOT NULL DEFAULT now(),lease_until timestamptz,error text,external_id text,confirmed_version bigint,parent_id uuid REFERENCES delivery,revision int NOT NULL DEFAULT 0,created_at timestamptz DEFAULT now(),UNIQUE(tenant_id,event_id,system_id,revision),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,event_id) REFERENCES outbox_event(tenant_id,id),FOREIGN KEY(tenant_id,system_id) REFERENCES integration_system(tenant_id,id),FOREIGN KEY(tenant_id,mapping_id) REFERENCES mapping_version(tenant_id,id));
CREATE INDEX delivery_due ON delivery(state,next_attempt_at);
CREATE TABLE delivery_attempt(id uuid PRIMARY KEY,tenant_id uuid,delivery_id uuid,attempt int,http_status int,business_success boolean,response jsonb,error text,created_at timestamptz DEFAULT now(),FOREIGN KEY(tenant_id,delivery_id) REFERENCES delivery(tenant_id,id));
CREATE TABLE inbox_message(tenant_id uuid,system_id uuid,message_id text,body_hash text,result jsonb,source_version bigint,created_at timestamptz DEFAULT now(),PRIMARY KEY(tenant_id,system_id,message_id),FOREIGN KEY(tenant_id,system_id) REFERENCES integration_system(tenant_id,id));
CREATE TABLE reconciliation_job(id uuid PRIMARY KEY,tenant_id uuid,system_id uuid,state text,results jsonb,created_at timestamptz DEFAULT now(),FOREIGN KEY(tenant_id,system_id) REFERENCES integration_system(tenant_id,id));
CREATE FUNCTION guard_published() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF TG_TABLE_NAME='schema_version' THEN IF OLD.status IN ('PUBLISHED','RETIRED') AND NEW.bundle IS DISTINCT FROM OLD.bundle THEN RAISE EXCEPTION 'IMMUTABLE_PUBLISHED_SCHEMA'; END IF; END IF;
 IF TG_TABLE_NAME='mapping_version' THEN IF OLD.state='PUBLISHED' AND NEW.config IS DISTINCT FROM OLD.config THEN RAISE EXCEPTION 'IMMUTABLE_PUBLISHED_MAPPING'; END IF; END IF;
 RETURN NEW; END; $$;
CREATE TRIGGER schema_immutable BEFORE UPDATE ON schema_version FOR EACH ROW EXECUTE FUNCTION guard_published();
CREATE TRIGGER mapping_immutable BEFORE UPDATE ON mapping_version FOR EACH ROW EXECUTE FUNCTION guard_published();
CREATE FUNCTION guard_material_identity() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF NEW.id IS DISTINCT FROM OLD.id OR NEW.tenant_id IS DISTINCT FROM OLD.tenant_id OR (OLD.material_no IS NOT NULL AND NEW.material_no IS DISTINCT FROM OLD.material_no) THEN RAISE EXCEPTION 'IMMUTABLE_MATERIAL_IDENTITY'; END IF; RETURN NEW; END; $$;
CREATE TRIGGER material_identity BEFORE UPDATE ON material FOR EACH ROW EXECUTE FUNCTION guard_material_identity();
